-- All identifiers are BIGINT (generated by src/ids.js) and exposed as decimal strings in JSON.
CREATE TABLE IF NOT EXISTS lead_capture_forms (
  id BIGINT PRIMARY KEY,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL,
  website_id BIGINT NOT NULL,
  name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','unpublished')),
  public_key TEXT NOT NULL UNIQUE,
  published_version_id BIGINT NULL,
  allowed_origins TEXT[] NOT NULL DEFAULT '{}',
  created_by_user_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, organization_id, name)
);

CREATE TABLE IF NOT EXISTS lead_capture_form_versions (
  id BIGINT PRIMARY KEY,
  form_id BIGINT NOT NULL REFERENCES lead_capture_forms(id) ON DELETE CASCADE,
  version INTEGER NOT NULL,
  schema_json JSONB NOT NULL,
  created_by_user_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (form_id, version)
);

CREATE TABLE IF NOT EXISTS lead_capture_submissions (
  id BIGINT PRIMARY KEY,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL,
  website_id BIGINT NOT NULL,
  form_id BIGINT NOT NULL REFERENCES lead_capture_forms(id),
  form_version_id BIGINT NOT NULL REFERENCES lead_capture_form_versions(id),
  fields_json JSONB NOT NULL,
  consent_json JSONB NULL,
  status TEXT NOT NULL DEFAULT 'received',
  idempotency_key_hash TEXT NOT NULL,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (form_id, idempotency_key_hash)   -- removes duplicate submissions
);
CREATE INDEX IF NOT EXISTS idx_lc_submissions_scope_time
  ON lead_capture_submissions (tenant_id, organization_id, form_id, received_at DESC);

CREATE TABLE IF NOT EXISTS crm_integrations (
  id BIGINT PRIMARY KEY,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL,
  form_id BIGINT NOT NULL UNIQUE REFERENCES lead_capture_forms(id) ON DELETE CASCADE,
  enabled BOOLEAN NOT NULL DEFAULT false,
  destination_url TEXT NOT NULL,
  secret_ref TEXT NOT NULL,                 -- name of an env/secret-manager entry, never the secret itself
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Doubles as the transactional outbox: written in the same transaction as the submission.
CREATE TABLE IF NOT EXISTS crm_delivery_jobs (
  id BIGINT PRIMARY KEY,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL,
  submission_id BIGINT NOT NULL UNIQUE REFERENCES lead_capture_submissions(id),
  state TEXT NOT NULL CHECK (state IN ('pending','delivered','needs_attention','dead_letter','not_configured')),
  attempt_count INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  delivered_at TIMESTAMPTZ NULL,
  external_crm_record_id TEXT NULL,
  last_error TEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_crm_jobs_due ON crm_delivery_jobs (next_attempt_at) WHERE state = 'pending';

CREATE TABLE IF NOT EXISTS crm_delivery_attempts (
  id BIGINT PRIMARY KEY,
  delivery_job_id BIGINT NOT NULL REFERENCES crm_delivery_jobs(id) ON DELETE CASCADE,
  attempt_number INTEGER NOT NULL,
  result_class TEXT NOT NULL,
  http_status INTEGER NULL,
  latency_ms INTEGER NULL,
  error_code TEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT PRIMARY KEY,
  actor_user_id BIGINT NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL,
  action TEXT NOT NULL,
  resource TEXT NOT NULL,
  resource_id BIGINT NULL,
  request_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
